CREATE TABLE data_permission_policies (id varchar(36) PRIMARY KEY,code varchar(128) NOT NULL,name text NOT NULL,scope varchar(16) NOT NULL,tenant_id varchar(128),published_version_number bigint,status varchar(16) NOT NULL,active_identity varchar(300) GENERATED ALWAYS AS (CASE WHEN deleted_at IS NULL THEN CONCAT(scope,':',COALESCE(tenant_id,''),':',LOWER(code)) ELSE NULL END) STORED,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY data_permission_policies_identity_unique(active_identity),KEY data_permission_policies_published_idx(status,scope,tenant_id,published_version_number),CHECK(scope IN('global','tenant')),CHECK(status IN('active','disabled')),CHECK(published_version_number IS NULL OR published_version_number>0),CHECK((scope='global' AND tenant_id IS NULL) OR (scope='tenant' AND tenant_id IS NOT NULL AND tenant_id<>'')));
CREATE TABLE data_permission_policy_versions (id varchar(36) PRIMARY KEY,policy_id varchar(36) NOT NULL,version_number bigint NOT NULL,document longtext NOT NULL,status varchar(16) NOT NULL,published_at timestamp(6) NULL,published_by text,active_version_number bigint GENERATED ALWAYS AS (CASE WHEN deleted_at IS NULL THEN version_number ELSE NULL END) STORED,active_published_policy_id varchar(36) GENERATED ALWAYS AS (CASE WHEN deleted_at IS NULL AND status='published' THEN policy_id ELSE NULL END) STORED,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY data_permission_policy_versions_number_unique(policy_id,active_version_number),UNIQUE KEY data_permission_policy_versions_published_unique(active_published_policy_id),KEY data_permission_policy_versions_status_idx(policy_id,status,version_number),CONSTRAINT data_permission_policy_versions_policy_fk FOREIGN KEY(policy_id) REFERENCES data_permission_policies(id),CHECK(version_number>0),CHECK(status IN('draft','published','archived')));
CREATE TABLE data_permission_policy_actions (id varchar(36) PRIMARY KEY,policy_version_id varchar(36) NOT NULL,resource varchar(128) NOT NULL,action varchar(64) NOT NULL,active_identity varchar(260) GENERATED ALWAYS AS (CASE WHEN deleted_at IS NULL THEN CONCAT(policy_version_id,':',resource,':',action) ELSE NULL END) STORED,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY data_permission_policy_actions_unique(active_identity),INDEX data_permission_policy_actions_lookup_idx(resource,action,policy_version_id),CONSTRAINT data_permission_policy_actions_version_fk FOREIGN KEY(policy_version_id) REFERENCES data_permission_policy_versions(id));
CREATE TRIGGER data_permission_policies_audit_bi BEFORE INSERT ON data_permission_policies FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1;
CREATE TRIGGER data_permission_policies_audit_bu BEFORE UPDATE ON data_permission_policies FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER data_permission_policy_versions_audit_bi BEFORE INSERT ON data_permission_policy_versions FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1;
CREATE TRIGGER data_permission_policy_versions_audit_bu BEFORE UPDATE ON data_permission_policy_versions FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER data_permission_policy_actions_audit_bi BEFORE INSERT ON data_permission_policy_actions FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1;
CREATE TRIGGER data_permission_policy_actions_audit_bu BEFORE UPDATE ON data_permission_policy_actions FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER data_permission_policies_audit_bd BEFORE DELETE ON data_permission_policies FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
CREATE TRIGGER data_permission_policy_versions_audit_bd BEFORE DELETE ON data_permission_policy_versions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
CREATE TRIGGER data_permission_policy_actions_audit_bd BEFORE DELETE ON data_permission_policy_actions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
